// 解码覆盖场到 dst（W*H 字节，0=场外 255=实心）。返回字节数。
inline int DecodeB376Field(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376FieldRLE;
    const unsigned char* pEnd = p + sizeof(kB376FieldRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 解码表层明暗到 dst（W*H 字节，参考图亮度 0..255，与覆盖场同网格）。返回字节数。
inline int DecodeB376Lum(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376LumRLE;
    const unsigned char* pEnd = p + sizeof(kB376LumRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 解码部件 ID 到 dst（W*H uint16，0=背景）。返回字节数。
inline int DecodeB376Id(unsigned short* dst) {
    int n = 0; const unsigned char* p = kB376IdRLE;
    const unsigned char* pEnd = p + sizeof(kB376IdRLE);
    while (n < kB376FieldW * kB376FieldH && p + 2 < pEnd) {
        int c = *p++;
        int v = p[0] | (p[1] << 8); p += 2;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned short)v;
    }
    return n;
}

// 解码骨架线切线角到 dst（W*H 字节，0..255 → 0..2π，0 为背景）。返回字节数。
inline int DecodeB376Angle(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376AngleRLE;
    const unsigned char* pEnd = p + sizeof(kB376AngleRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 解码背景静态掩码到 dst（W*H 字节，1=灰绿背景不移动，0=前景移动）。返回字节数。
inline int DecodeB376Static(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376StaticRLE;
    const unsigned char* pEnd = p + sizeof(kB376StaticRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 解码轮廓弧长参数场到 dst（W*H 字节，0..255 = 绕单元外轮廓位置+相位去同步）。返回字节数。
inline int DecodeB376Arc(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376ArcRLE;
    const unsigned char* pEnd = p + sizeof(kB376ArcRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 解码边缘带权重到 dst（W*H 字节，0..255：轮廓附近高，内部/外部 0）。返回字节数。
inline int DecodeB376Edge(unsigned char* dst) {
    int n = 0; const unsigned char* p = kB376EdgeRLE;
    const unsigned char* pEnd = p + sizeof(kB376EdgeRLE);
    while (n < kB376FieldW * kB376FieldH && p + 1 < pEnd) {
        int c = *p++, v = *p++;
        if (n + c > kB376FieldW * kB376FieldH) c = kB376FieldW * kB376FieldH - n;
        while (c--) dst[n++] = (unsigned char)v;
    }
    return n;
}

// 液态流动（边缘版，像 Psychedelic 轮廓线在水中流动）：
//   每个运动单体的【边缘】沿周长传播的行波起伏（几何形变，内部稳定），
//   位移 = 波(arc 位置) * 边缘带权重 * 幅度，方向沿径向（对边界近似法线）。
//   每单体用自己的相位 → 边缘独立流动；速度接 speed，幅度接 amp(滑杆)。
// 前向散射：源像素按形变位移搬到目标（覆盖+明暗+弧长三场一起搬）。
// covOut/lumOut/arcOut 由调用方分配 W*H 字节。每帧调一次。
inline void B376DisplaceFields(float t, float speed, float amp,
                               unsigned char* covOut, unsigned char* lumOut, unsigned char* arcOut) {
    const int n = kB376FieldW * kB376FieldH;
    const float W = (float)kB376FieldW, H = (float)kB376FieldH;
    static std::vector<unsigned char> sCov, sLum, sArc, sSta, sEdge;
    static std::vector<unsigned short> sId;
    static std::once_flag sFlag;
    std::call_once(sFlag, [n] {
        sCov.resize(n); sLum.resize(n); sId.resize(n); sArc.resize(n); sSta.resize(n); sEdge.resize(n);
        DecodeB376Field(sCov.data()); DecodeB376Lum(sLum.data());
        DecodeB376Id(sId.data()); DecodeB376Arc(sArc.data()); DecodeB376Static(sSta.data()); DecodeB376Edge(sEdge.data());
    });
    std::memset(covOut, 0, n);
    std::memset(lumOut, 0, n);
    std::memset(arcOut, 0, n);
    const float twoPi = 6.2831853f;
    for (int y = 0; y < kB376FieldH; ++y) {
        int row = y * kB376FieldW;
        for (int x = 0; x < kB376FieldW; ++x) {
            unsigned short idv = sId[row + x];
            if (idv == 0) continue;
            int tx, ty;
            if (sSta[row + x]) { tx = x; ty = y; }   // 灰绿背景：不动
            else {
                int i = idv - 1;
                float cxi = kB376Center[i][0] * W, cyi = kB376Center[i][1] * H;
                float rad = kB376Axis[i][2];      // 封顶半径 px
                float ph = kB376Axis[i][3];       // 每单体相位（独立流动）
                float tt = t * speed;
                float arcv = sArc[row + x] / 255.0f;   // 轮廓弧长位置 0..1
                float band = sEdge[row + x] / 255.0f;  // 边缘带权重（内部 0）
                float wave = std::sin(twoPi * (arcv + tt) + ph);   // 沿周长传播的波
                float A = amp * rad * 0.12f;     // 形变幅度 ≈ 半径12%
                float rx = (float)x - cxi, ry = (float)y - cyi;
                float rr = std::sqrt(rx*rx + ry*ry);
                float inv = rr > 0.001f ? 1.0f / rr : 0.0f;
                float dr = wave * A * band;     // 只作用于边缘带
                float ox = rx * inv * dr, oy = ry * inv * dr;
                tx = x + (int)std::lround(ox);
                ty = y + (int)std::lround(oy);
                if (tx < 0) tx = 0; else if (tx >= kB376FieldW) tx = kB376FieldW - 1;
                if (ty < 0) ty = 0; else if (ty >= kB376FieldH) ty = kB376FieldH - 1;
            }
            int dst = ty * kB376FieldW + tx;
            unsigned char c = sCov[row + x];
            if (c > covOut[dst]) covOut[dst] = c;
            unsigned char l = sLum[row + x];
            if (l > lumOut[dst]) lumOut[dst] = l;
            unsigned char ar = sArc[row + x];
            if (ar > arcOut[dst]) arcOut[dst] = ar;
        }
    }
}
